debug.error_function_source:
async def act(page):
    """
    From the current Create Product Settings page, proceed to the product form and create
    a simple product named 'Lelelumon Yoga Mat' priced at 769.99, size 'uni-size', color 'black',
    quantity 42, set to In Stock, then SAVE. The Save action is the final action (it may navigate).
    """
    import asyncio

    # There are no knowledge_base helper functions available in the environment (none were provided),
    # so none are used. All actions below use Playwright page.get_by_role() and select_option() as required.

    # Best-effort: close any visible popup that might block interactions.
    for close_label in ("Close", "close", "Dismiss", "×", "Close (Esc)"):
        try:
            await page.get_by_role("button", name=close_label).click()
            await asyncio.sleep(0.3)
            break
        except Exception:
            pass

    # Click the Continue button under the 'Continue' row to show the product form.
    # Use the explicit row -> button path to avoid ambiguous top-level matches.
    try:
        await page.get_by_role("row", name="Continue").get_by_role("button", name="Continue").click()
    except Exception:
        # Fallback: top-level Continue button
        try:
            await page.get_by_role("button", name="Continue").click()
        except Exception:
            # If unable to click Continue, assume form may already be visible; continue.
            pass

    # Wait briefly for form to load. Prefer waiting for the Name textbox to appear.
    try:
        await page.get_by_role("textbox", name="Name").wait_for(timeout=7000)
    except Exception:
        # fallback wait
        await asyncio.sleep(1)

    # Fill product Name
    try:
        await page.get_by_role("textbox", name="Name").fill("Lelelumon Yoga Mat")
    except Exception:
        try:
            await page.get_by_role("textbox").nth(0).fill("Lelelumon Yoga Mat")
        except Exception:
            pass

    # Fill Price
    try:
        await page.get_by_role("textbox", name="Price").fill("769.99")
    except Exception:
        for alt in ("Product Price", "price", "Price ($)"):
            try:
                await page.get_by_role("textbox", name=alt).fill("769.99")
                break
            except Exception:
                continue

    # Select Size attribute using combobox.select_option()
    try:
        await page.get_by_role("combobox", name="Size").select_option(label="uni-size")
    except Exception:
        for opt in ("Uni-size", "uni size", "UNI-SIZE"):
            try:
                await page.get_by_role("combobox", name="Size").select_option(label=opt)
                break
            except Exception:
                continue

    # Select Color attribute using combobox.select_option()
    try:
        await page.get_by_role("combobox", name="Color").select_option(label="black")
    except Exception:
        for name_variant in ("Colour", "color", "Color"):
            try:
                await page.get_by_role("combobox", name=name_variant).select_option(label="black")
                break
            except Exception:
                continue

    # Open Inventory tab/section so we can set Qty and stock status
    try:
        await page.get_by_role("tab", name="Inventory").click()
        await asyncio.sleep(0.35)
    except Exception:
        for role_name in ("button", "link"):
            try:
                await page.get_by_role(role_name, name="Inventory").click()
                await asyncio.sleep(0.35)
                break
            except Exception:
                continue

    # Set Qty to 42
    qty_set = False
    for qty_name in ("Qty", "Quantity", "Qty."):
        try:
            await page.get_by_role("textbox", name=qty_name).fill("42")
            qty_set = True
            break
        except Exception:
            continue
    if not qty_set:
        # positional fallback
        try:
            await page.get_by_role("textbox").nth(2).fill("42")
        except Exception:
            pass

    # Set Stock Availability to In Stock via combobox.select_option()
    try:
        await page.get_by_role("combobox", name="Stock Availability").select_option(label="In Stock")
    except Exception:
        for alt in ("Stock", "Stock Status", "Availability"):
            try:
                await page.get_by_role("combobox", name=alt).select_option(label="In Stock")
                break
            except Exception:
                continue

    # FINAL ACTION: Click Save. Use a parent group to avoid ambiguous matches. Save may navigate away, so it must be last.
    save_clicked = False
    parent_candidates = [
        page.get_by_role("group", name="Page Actions"),
        page.get_by_role("group", name="Actions"),
        page.get_by_role("toolbar"),
        page.get_by_role("banner"),
    ]
    for parent in parent_candidates:
        try:
            await parent.wait_for(timeout=1500)
            await parent.get_by_role("button", name="Save").click()
            save_clicked = True
            break
        except Exception:
            continue

    if not save_clicked:
        try:
            await page.get_by_role("button", name="Save").click()
            save_clicked = True
        except Exception:
            # nothing more reliable we can do here
            await asyncio.sleep(1)

    # Wait for the save/navigation to complete (if it navigates away)
    try:
        await page.wait_for_load_state("networkidle")
    except Exception:
        await asyncio.sleep(1)

