    for close_label in ("Close", "close", "Dismiss", "×", "Close (Esc)"):
        try:
            await page.get_by_role("button", name=close_label).click()
            await asyncio.sleep(0.3)
            break
        except Exception:
            pass

    # Click the Continue button under the 'Continue' row to show the product form.
    # Use the explicit row -> button path to avoid ambiguous top-level matches.
    try:
        await page.get_by_role("row", name="Continue").get_by_role("button", name="Continue").click()
    except Exception:
        # Fallback: top-level Continue button
