    # There are no knowledge_base helper functions available in the environment (none were provided),
    # so none are used. All actions below use Playwright page.get_by_role() and select_option() as required.

    # Best-effort: close any visible popup that might block interactions.
    for close_label in ("Close", "close", "Dismiss", "×", "Close (Esc)"):
        try:
            await page.get_by_role("button", name=close_label).click()
            await asyncio.sleep(0.3)
            break
        except Exception:
            pass

    # Click the Continue button under the 'Continue' row to show the product form.
    # Use the explicit row -> button path to avoid ambiguous top-level matches.
    try:
        await page.get_by_role("row", name="Continue").get_by_role("button", name="Continue").click()
    except Exception:
        # Fallback: top-level Continue button
        try:
            await page.get_by_role("button", name="Continue").click()
        except Exception:
            # If unable to click Continue, assume form may already be visible; continue.
            pass

    # Wait briefly for form to load. Prefer waiting for the Name textbox to appear.
    try:
        await page.get_by_role("textbox", name="Name").wait_for(timeout=7000)
    except Exception:
        # fallback wait
        await asyncio.sleep(1)

    # Fill product Name
    try:
        await page.get_by_role("textbox", name="Name").fill("Lelelumon Yoga Mat")
    except Exception:
        try:
            await page.get_by_role("textbox").nth(0).fill("Lelelumon Yoga Mat")
        except Exception:
            pass

    # Fill Price
    try:
        await page.get_by_role("textbox", name="Price").fill("769.99")
    except Exception:
        for alt in ("Product Price", "price", "Price ($)"):
            try:
                await page.get_by_role("textbox", name=alt).fill("769.99")
                break
            except Exception:
                continue

    # Select Size attribute using combobox.select_option()
    try:
        await page.get_by_role("combobox", name="Size").select_option(label="uni-size")
